import json
from datetime import datetime

events = [
    {'name': 'Meeting', 'timestamp': datetime(2024, 5, 10, 9, 0)},
    {'name': 'Deadline', 'timestamp': datetime(2024, 5, 12, 17, 30)}
]

def default_serializer(obj):
    if isinstance(obj, datetime):
        return obj.isoformat()
    raise TypeError(f'Object of type {type(obj).__name__} is not JSON serializable')

json_output = json.dumps(events, default=default_serializer, indent=2)
print(json_output)

import json

inventory = [
    {'sku': 'A101', 'name': 'Notebook', 'price': 3.50},
    {'sku': 'B202', 'name': 'Pen', 'price': 1.20},
    {'sku': None, 'name': 'Eraser', 'price': 0.80},
    {'sku': 'C303', 'name': 'Pencil', 'price': -2.0}
]

valid = []
for item in inventory:
    if all(k in item for k in ('sku', 'name', 'price')) and item['sku'] is not None and item['price'] >= 0:
        valid.append(item)

try:
    with open('inventory.json', 'w') as f:
        json.dump(valid, f, indent=2)
    print('Export completed successfully.')
except IOError as e:
    print(f'Error writing file: {e}')

